{
  "html": "<div class="e3-wrapper" data-ui-unit="E3">
  <fieldset class="e3-group">
    <legend class="e3-legend">상담 분야</legend>
    <div class="e3-chips">
      <button type="button" class="e3-chip e3-chip--active" disabled aria-pressed="true">
        전체
      </button>
      <button type="button" class="e3-chip" disabled aria-pressed="false">
        커리어
      </button>
      <button type="button" class="e3-chip" disabled aria-pressed="false">
        자소서
      </button>
      <button type="button" class="e3-chip" disabled aria-pressed="false">
        면접
      </button>
    </div>
  </fieldset>
</div>",
  "css": ".e3-wrapper {
  --ink: #283548;
  --muted: #566273;
  --surface: #fff;
}

.e3-group {
  border: none;
  padding: 0;
  margin: 0;
  min-height: 36px;
}

.e3-legend {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.e3-chips {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  padding: 12px 0;
}

.e3-chip {
  font: 500 14px/1.57 "Noto Sans KR", sans-serif;
  background: var(--surface);
  color: var(--muted);
  border-radius: 18px;
  padding: 0 12px;
  min-height: 36px;
  cursor: default;
  white-space: nowrap;
}

.e3-chip--active {
  background: var(--ink);
  color: var(--surface);
}"
}
